/**
 * Ambient module declarations for @salesforce/retail-react-app.
 *
 * This package ships without TypeScript types. We declare the modules we
 * import in overrides/ with real types where we know the shape, and fall
 * back to an untyped catch-all for everything else.
 *
 * Add specific declarations here as more subpaths are consumed in overrides/.
 */

declare module '@salesforce/retail-react-app/app/theme' {
  import type { ChakraTheme } from '@chakra-ui/react';
  const theme: ChakraTheme;
  export default theme;
}

// Matches the pinned react-router-dom 5.3.4 (see package.json) — the package ships
// without its own types and no @types/react-router-dom is installed, so this mirrors
// that version's real shapes (history's Location/LocationDescriptor, match) rather
// than a generic approximation.
declare module 'react-router-dom' {
  import type React from 'react';

  interface Location<TState = unknown> {
    pathname: string;
    search: string;
    hash: string;
    state: TState;
    key?: string;
  }
  export function useLocation<TState = unknown>(): Location<TState>;

  // Every declared param is optional — a route pattern doesn't guarantee a segment
  // was actually present in the matched URL. Default is `{}` in the real react-router
  // types (so an unparameterised useParams()'s properties correctly fail to resolve);
  // `NonNullable<unknown>` is the eslint-approved equivalent — our ban-types rule
  // rejects a literal `{}`, and `Record<string, never>` was tried and rejected in
  // review: it types every property as `never`, which is assignable to anything and
  // so silently passes property access that should be a compile error.
  export function useParams<TParams extends { [K in keyof TParams]?: string } = NonNullable<unknown>>(): TParams;

  type To<TState = unknown> = string | { pathname?: string; search?: string; hash?: string; state?: TState };

  interface LinkProps<TState = unknown> extends React.AnchorHTMLAttributes<HTMLAnchorElement> {
    to: To<TState>;
    replace?: boolean;
  }
  export const Link: React.ForwardRefExoticComponent<LinkProps & React.RefAttributes<HTMLAnchorElement>>;

  interface match<TParams extends { [K in keyof TParams]?: string } = NonNullable<unknown>> {
    params: TParams;
    isExact: boolean;
    path: string;
    url: string;
  }

  interface NavLinkProps extends LinkProps {
    exact?: boolean;
    activeClassName?: string;
    activeStyle?: React.CSSProperties;
    isActive?: (match: match | null, location: Location) => boolean;
  }
  export const NavLink: React.ForwardRefExoticComponent<NavLinkProps & React.RefAttributes<HTMLAnchorElement>>;
}

declare module '@salesforce/pwa-kit-react-sdk/ssr/universal/utils' {
  export function getAssetUrl(path: string): string;
}

declare module '@salesforce/pwa-kit-runtime/utils/ssr-config' {
  export function getConfig(): { app: Record<string, unknown> };
}

declare module '@salesforce/pwa-kit-react-sdk/ssr/universal/hooks' {
  type ServerResponse = {
    set: (name: string, value: string) => void;
    status: (code: number) => ServerResponse;
  };
  export function useServerContext(): {
    req?: any;
    res?: ServerResponse;
  };
  export function useCorrelationId(): { correlationId: string };
}

declare module '@salesforce/pwa-kit-runtime/utils/ssr-namespace-paths' {
  export const getEnvBasePath: () => string;
  export const slasPrivateProxyPath: string;
}

declare module '@salesforce/pwa-kit-runtime/utils/logger-factory' {
  const createLogger: (opts: { packageName: string }) => any;
  export default createLogger;
}

declare module '@salesforce/pwa-kit-react-sdk/ssr/universal/components/with-react-query' {
  export function withReactQuery(Component: any, options?: any): any;
}

declare module '@salesforce/pwa-kit-react-sdk/utils/url' {
  export function getAppOrigin(): string;
}

declare module '@loadable/component' {
  const loadable: (fn: () => Promise<any>, opts?: any) => any;
  export default loadable;
}

// Static asset imports (webpack url-loader / asset modules)
declare module '*.svg' {
  const src: string;
  export default src;
}

// Catch-all for all other @salesforce/retail-react-app subpaths not declared above.
declare module '@salesforce/retail-react-app/*';

// @vitejs/plugin-react uses package exports only (no root index.d.ts), which
// TypeScript 4.9 with moduleResolution:node cannot resolve. Minimal shim — the
// actual Plugin return type depends on vite types that are equally unreachable
// from TS 4.9. Once the project upgrades to TS 5+ this declaration can be removed.
declare module '@vitejs/plugin-react' {
  interface Options {
    include?: string | RegExp | Array<string | RegExp>;
    exclude?: string | RegExp | Array<string | RegExp>;
    jsxImportSource?: string;
  }
  // Return typed as any: Plugin from vite is not resolvable under moduleResolution:node.
  function react(options?: Options): any;
  export default react;
}

