########## pdpProductInfo/index.tsx ##########
import React from 'react';
import DOMPurify from 'isomorphic-dompurify';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { SPACE_DESCRIPTION_TO_META, SPACE_MODEL_INFO_TO_STYLE_CODE } from 'app/theme/components/pdpProductInfo';

type PdpProductInfoProps = {
  name: string;
  price: string;
  description?: string;
  modelInfo?: string;
  styleCode?: string;
};

// ---------------------------------------------------------------------------
// All styling lives in theme/components/pdpProductInfo.ts and is consumed via
// useMultiStyleConfig('ZimmPdpProductInfo') → __css. The only exceptions are the
// two conditional bottom margins, which depend on which optional props were
// supplied and so cannot be expressed in baseStyle; their values are imported
// from the theme file rather than written here.
// ---------------------------------------------------------------------------

/**
 * Renders static product information for the PDP: name, price, description,
 * and optional model copy / style code.
 */
const PdpProductInfo = ({ name, price, description, modelInfo, styleCode }: PdpProductInfoProps) => {
  const styles = useMultiStyleConfig('ZimmPdpProductInfo', {});
  const hasMeta = Boolean(modelInfo || styleCode);

  return (
    <chakra.div>
      <chakra.h1 __css={styles.name}>{name}</chakra.h1>

      <chakra.p data-testid="product-price" __css={styles.price}>
        {price}
      </chakra.p>

      {description && (
        <chakra.div
          data-testid="product-description"
          __css={styles.description}
          marginBottom={hasMeta ? SPACE_DESCRIPTION_TO_META : 0}
          dangerouslySetInnerHTML={{ __html: DOMPurify.sanitize(description) }}
        />
      )}

      {hasMeta && (
        <chakra.div>
          {modelInfo && (
            <chakra.div
              data-testid="product-model-info"
              __css={styles.modelInfo}
              marginBottom={styleCode ? SPACE_MODEL_INFO_TO_STYLE_CODE : 0}
              dangerouslySetInnerHTML={{ __html: DOMPurify.sanitize(modelInfo) }}
            />
          )}
          {styleCode && (
            <chakra.p data-testid="product-style-code" __css={styles.styleCode}>
              Style Code: {styleCode}
            </chakra.p>
          )}
        </chakra.div>
      )}
    </chakra.div>
  );
};

export { PdpProductInfo };
export default PdpProductInfo;

########## theme/components/pdpProductInfo.ts ##########
// Theme config for the PDP static product information block
// (overrides/app/components/pdpProductInfo). Level 3 of the overrideStyling.md
// hierarchy — all styling for the component lives here and is consumed via
// useMultiStyleConfig('ZimmPdpProductInfo') → __css. Nothing is styled at the call
// site except the two conditional margins noted below, which depend on which
// optional props were supplied and so cannot be expressed in baseStyle.
//
// Levels 1 and 2 are still preferred *inside* this file: `textStyle` for typography
// that has a registered token, and semantic colour/spacing token strings
// ('text.default', 'l', '4xl') rather than raw values. The --zimm-* vars below are
// the only level-4 escapes, each for a documented gap.

// ---------------------------------------------------------------------------
// Body-font text treatment
// ---------------------------------------------------------------------------
// Not a `textStyle`, deliberately: no entry in theme/foundation/typography.ts
// matches this family/weight/lineHeight combination, and the weight is still
// unresolved (FONT_REGULAR vs FONT_MEDIUM) pending UI-designer sign-off.
//
// Once the weight is confirmed, register the combination as a text style in
// typography.ts (Tier 1 — UI Designer) and replace these spreads with a single
// `textStyle` entry on each part, deleting these consts.
const BODY_TEXT = {
  fontFamily: 'var(--zimm-font-family-body)',
  fontWeight: 'var(--zimm-font-weight-medium)',
  lineHeight: 'var(--zimm-font-lineheight-2xs)',
} as const;

/** Price — same treatment as the meta copy, one step up the size scale. */
const PRICE_TEXT = { ...BODY_TEXT, fontSize: 'var(--zimm-font-size-2xs)' } as const;

/** Model info and style code — the smallest body size. */
const META_TEXT = { ...BODY_TEXT, fontSize: 'var(--zimm-font-size-3xs)' } as const;

// ---------------------------------------------------------------------------
// Conditional spacing
// ---------------------------------------------------------------------------
// Applied as direct Chakra props at the call site (level 2) rather than in
// baseStyle, because each collapses to 0 when the following block is absent.
// The values are named here so the token lives with the rest of the styling.
//
// Both are numeric --zimm-scale-* aliases with no named key in spacing.ts, which
// is why they are vars rather than semantic strings. Confirm against Figma and
// promote to a named scale entry if either turns out to be a reusable step.

/** 44px — gap between the description and the model-info / style-code group. */
export const SPACE_DESCRIPTION_TO_META = 'var(--zimm-scale-1100)';

/** 28px — gap between model info and style code. */
export const SPACE_MODEL_INFO_TO_STYLE_CODE = 'var(--zimm-scale-700)';

// Horizontal inset applied to the two prose blocks on mobile only. Semantic
// spacing key (level 2), kept in one place because both parts share it.
const PROSE_PADDING_RIGHT = { base: '3xl', md: 0 } as const;

export const ZimmPdpProductInfo = {
  parts: ['name', 'price', 'description', 'modelInfo', 'styleCode'],
  baseStyle: {
    name: {
      textStyle: 'heading3',
      color: 'text.default',
      marginBottom: 'l',
    },

    price: {
      ...PRICE_TEXT,
      color: 'text.default',
      marginBottom: 'l',
    },

    // Renders sanitized CMS/PIM HTML — see the DOMPurify call at the call site.
    description: {
      textStyle: 'body2',
      color: 'text.default',
      paddingRight: PROSE_PADDING_RIGHT,
    },

    // Also sanitized HTML. marginBottom is supplied at the call site.
    modelInfo: {
      ...META_TEXT,
      color: 'text.default',
      paddingRight: PROSE_PADDING_RIGHT,
    },

    styleCode: {
      ...META_TEXT,
      color: 'text.secondary',
      marginBottom: '4xl',
    },
  },
};

