########## zimmPageToolbar/index.tsx ##########
import React from 'react';
import { Link as RouteLink } from 'react-router-dom';
import { Box, Text } from '@salesforce/retail-react-app/app/components/shared/ui';

type PageToolbarVariant = 'breadcrumbs' | 'recently-viewed' | 'section-title';

type ZimmPageToolbarProps =
  | { variant: 'breadcrumbs'; children?: React.ReactNode }
  | {
      variant: 'recently-viewed' | 'section-title';
      /** Section or list heading. */
      heading: string;
      /** CTA label shown to the right of the heading. */
      linkText?: string;
      /** CTA destination. */
      linkHref?: string;
    };

// Per-variant padding. '2xl' and '3xl' are the named spacing keys behind
// --zimm-scale-800 (32px) and --zimm-scale-1000 (40px) — see
// foundation/zimmTokens.ts, which defines both aliases from those keys. Using the
// semantic keys keeps this at level 2 of the overrideStyling.md hierarchy rather
// than reaching for the numeric vars.
//
// Keyed per variant because all three treatments share one wrapper: breadcrumbs
// needs a 40px right inset where the other two keep 80px, so a single shared value
// can no longer express every side.
const PADDING = {
  // Breadcrumbs: 40px horizontal, 32px vertical.
  breadcrumbs: { pt: '2xl', pb: '2xl', pl: '3xl', pr: '3xl' },
  'recently-viewed': { pt: 'xs', pb: '2xl', pl: '3xl', pr: '5xl' },
  'section-title': { pt: 'xs', pb: '2xl', pl: '3xl', pr: '5xl' },
} satisfies Record<PageToolbarVariant, { pt: string; pb: string; pl: string; pr: string }>;

/**
 * Structural wrapper for breadcrumb, recently-viewed, and section-title treatments.
 * Port of the handover `zimm-page-toolbar` element.
 */
const ZimmPageToolbar = (props: ZimmPageToolbarProps) => {
  return (
    <Box {...PADDING[props.variant]} backgroundColor="background.07">
      {props.variant === 'recently-viewed' || props.variant === 'section-title' ? (
        <Box display="flex" alignItems="center" justifyContent="space-between" width="100%">
          <Text as="h2" textStyle="heading3" color="text.default" m={0}>
            {props.heading}
          </Text>
          {props.linkText && props.linkHref && (
            <Text
              as={RouteLink}
              to={props.linkHref}
              textStyle="linkLg"
              color="text.default"
              textDecoration="none"
              _hover={{ color: 'text.secondary', textDecoration: 'none', opacity: 0.6 }}
              className="zimm-focus-visible"
              sx={{
                transition:
                  'color var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard), opacity var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard)',
              }}
            >
              {props.linkText}
            </Text>
          )}
        </Box>
      ) : props.variant === 'breadcrumbs' ? (
        <Box opacity={0.8}>{props.children}</Box>
      ) : null}
