import React from 'react';
import { Link as RouteLink } from 'react-router-dom';
import { Box, Text } from '@chakra-ui/react';

type BreadcrumbCategory = {
  id: string;
  name: string;
};

const categoryUrlBuilder = (category: BreadcrumbCategory) =>
  encodeURI(`/category/${category.id}`);

type BreadcrumbProps = {
  categories: readonly BreadcrumbCategory[];
  /**
   * Non-link terminal crumb — typically the product name.
   * Breaks to a new line on mobile; stays inline on desktop.
   */
  currentPage?: string;
};

const BASE_STYLE = {
  textStyle: 'caption',
  textTransform: 'uppercase' as const,
  color: 'text.default',
};

const LINK_PROPS = {
  ...BASE_STYLE,
  textDecoration: 'none',
  _hover: { opacity: 0.6 },
  sx: {
    transition: 'opacity var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard)',
  },
};

const Separator = () => (
  <Text as="span" aria-hidden="true" {...BASE_STYLE} mx="2xs">
    /
  </Text>
);

/**
 * PDP breadcrumb reflecting the product's category path.
 * HOME is always the first crumb; currentPage is the non-link terminal item.
 */
const Breadcrumb = ({ categories, currentPage }: BreadcrumbProps) => {
  const hasMoreAfterHome = categories.length > 0 || Boolean(currentPage);

  return (
    <Box as="nav" aria-label="Breadcrumb">
      <Box as="ol" listStyleType="none" m={0} p={0} sx={{ paddingInlineStart: 0 }}>
        <Box as="li" display="inline">
          <Text as={RouteLink} to="/" {...LINK_PROPS}>
            Home
          </Text>
          {hasMoreAfterHome && <Separator />}
        </Box>

        {categories.map((category, index) => {
          const isLastCrumb = index === categories.length - 1 && !currentPage;
          return (
            <Box as="li" key={category.id} display="inline">
              <Text as={RouteLink} to={categoryUrlBuilder(category)} {...LINK_PROPS}>
                {category.name}
              </Text>
              {!isLastCrumb && <Separator />}
            </Box>
          );
        })}

        {currentPage && (
          <Box as="li" display={{ base: 'block', md: 'inline' }}>
            <Text as="span" aria-current="page" {...BASE_STYLE}>
              {currentPage}
            </Text>
          </Box>
        )}
      </Box>
    </Box>
  );
};

export type { BreadcrumbCategory };
