########## pages/product-detail/index.tsx ##########
import React from 'react';
import { useParams } from 'react-router-dom';
import { useIntl } from 'react-intl';
import { useCategory, useProduct } from '@salesforce/commerce-sdk-react';
import { Box, Skeleton, Text } from '@salesforce/retail-react-app/app/components/shared/ui';
import PdpProductInfo from '../../components/pdpProductInfo';
import type { BreadcrumbCategory } from '../../components/breadcrumb';
import Breadcrumb from '../../components/breadcrumb';
import ZimmPageToolbar from '../../components/ui-kits/atoms/zimmPageToolbar';
import { extractModelLine } from '../../utils/productData';
import type { ProductWithSizeFit } from '../../types';

// Provisional — no matching zimm token; pending designer sign-off.
export const PDP_OPTIONS_COLUMN_WIDTH = '360px';


const ProductDetail = () => {
  const { productId } = useParams<{ productId: string }>();
  const intl = useIntl();

  const {
    data: product,
    isLoading,
    error,
  } = useProduct({ parameters: { id: productId } }, { enabled: Boolean(productId) });

  // Enabled only after product loads — category ID is not known until then.
  const { data: category, isError: isCategoryError } = useCategory(
    { parameters: { id: product?.primaryCategoryId ?? null, levels: 1 } },
    { enabled: Boolean(product?.primaryCategoryId) },
  );

  // ancestors (parentCategoryTree) + leaf category → full breadcrumb path.
  // If the category call fails, degrades to an empty path (Home > Product Name only).
  const breadcrumbCategories =
    !category || isCategoryError
      ? []
      : (category.parentCategoryTree ?? []).filter(
          (p): p is BreadcrumbCategory => Boolean(p.id) && Boolean(p.name),
        );

  const formattedPrice =
    product?.price != null && product?.currency
      ? intl.formatNumber(product.price, { style: 'currency', currency: product.currency })
      : '';

  return (
    <Box className="sf-product-detail-page" data-testid="product-details-page">
      <Box
        display="grid"
        gridTemplateColumns={{ base: '1fr', md: `1fr ${PDP_OPTIONS_COLUMN_WIDTH}` }}
        columnGap={{ base: 0, md: 'var(--zimm-scale-4500)' }}
        alignItems="start"
      >
        {/* Gallery column — images out of scope, placeholder maintains layout */}
        <Box minW={0} backgroundColor="background.02" aspectRatio={{ base: '3/4', md: '49/60' }} />

        {/* Options column */}
        <Box
          minW={0}
          pl={{ base: 'var(--zimm-scale-800)', md: 0 }}
          pr={{ base: 'var(--zimm-scale-800)', md: 'var(--zimm-scale-3500)' }}
          pt={{ base: 'var(--zimm-scale-400)', md: 0 }}
        >
          {error ? (
            <Text color="status.error">Unable to load product information.</Text>
          ) : isLoading ? (
            <>
              <Skeleton height="var(--zimm-scale-800)" mb="m" />
              <Skeleton height="var(--zimm-scale-500)" mb="xl" width="40%" />
              <Skeleton height="var(--zimm-scale-5xl)" />
            </>
          ) : (
            <PdpProductInfo
              name={product?.name ?? ''}
              price={formattedPrice}
              description={product?.shortDescription || product?.longDescription}
              modelInfo={extractModelLine((product as ProductWithSizeFit | undefined)?.c_sizeFit)}
              styleCode={product?.id}
            />
          )}
        </Box>
      </Box>

      <ZimmPageToolbar variant="breadcrumbs">
        <Breadcrumb categories={breadcrumbCategories} currentPage={product?.name} />
      </ZimmPageToolbar>
    </Box>
  );
};

ProductDetail.getTemplateName = () => 'product-detail';

export { ProductDetail };
export default ProductDetail;

########## pages/product-detail/index.test.ts ##########
import { describe, test, expect } from 'vitest';
import { extractModelLine } from '../../utils/productData';

describe('extractModelLine', () => {
  test('returns the "Model is" bullet from a sizeFit HTML string', () => {
    const html =
      '<ul><li>Fitted at the waist</li><li>Relaxed through hips and legs</li><li>Model is 5\'9.5"/178 cm, bust size 32C/10C and wears a size 0</li></ul>';
    expect(extractModelLine(html)).toBe('Model is 5\'9.5"/178 cm, bust size 32C/10C and wears a size 0');
  });

  test('returns undefined when no "Model is" bullet is present', () => {
    const html = '<ul><li>Fitted at the waist</li><li>Relaxed through hips and legs</li></ul>';
    expect(extractModelLine(html)).toBeUndefined();
  });

  test('returns undefined for an empty string', () => {
    expect(extractModelLine('')).toBeUndefined();
  });

  test('returns undefined for undefined input', () => {
    expect(extractModelLine(undefined)).toBeUndefined();
  });

  test('trims whitespace from the matched content', () => {
    const html = '<ul><li>  Model is 5\'6"/168 cm and wears a size S  </li></ul>';
    expect(extractModelLine(html)).toBe('Model is 5\'6"/168 cm and wears a size S');
  });
});

