import type { Meta, StoryObj } from '@storybook/react';
import { expect, within } from 'storybook/test';
import PdpProductInfo from './index';

const meta: Meta<typeof PdpProductInfo> = {
  title: 'Commerce/PdpProductInfo',
  component: PdpProductInfo,
};

export default meta;
type Story = StoryObj<typeof PdpProductInfo>;

export const Default: Story = {
  args: {
    name: 'Indra Plunge Halter Maxi Dress',
    price: '$1,100',
    description:
      'A silk halter neck maxi dress featuring a plunging V neckline, fitted waist with exposed sides and an open back with beaded self ties.',
    modelInfo: "Model is 5'10 Tall/177cm and is wearing a US Size 6, runs true to size.",
    styleCode: '7300JS261',
  },
};

